#include <iostream>
#include <sstream>
#include <string>
using namespace std;

struct Person { string name; int age; double salary; };

string toJson(const Person& p) {
    ostringstream oss;
    oss << "{\"name\":\"" << p.name << "\",\"age\":" << p.age << ",\"salary\":" << p.salary << "}";
    return oss.str();
}

int main() {
    Person p = {"Alice", 30, 75000.50};
    cout << toJson(p) << endl;
    return 0;
}
